<template>
	<view style="margin:10px;">
		<up-form
	    		labelPosition="left"
	    		:model="expertForm"
	    		:rules="rules"
	    		ref="form1"
				labelAlign="left"
	    >
		
		    <up-form-item
		    		label="头像:"
		    		prop="avatar"
		    		:borderBottom="true"
		    		ref="item1"
		    		label-width="75"
		    >
				<up-upload
						:fileList="fileList1"
						@afterRead="afterRead"
						@delete="deletePic"
						name="1"
						multiple
						:maxCount="10"
						:previewFullImage="true"
					></up-upload>
		    </up-form-item>
			
	    	<up-form-item
	    			label="姓名:"
	    			prop="expertName"
	    			:borderBottom="true"
	    			ref="item1"
					label-width="75"
	    	>
	    		<up-input
	    				v-model="expertForm.expertName"
	    				border="none"
						placeholder="请输入您的姓名"
	    		></up-input>
	    	</up-form-item>
			
	    	<up-form-item
	    			label="性别:"
	    			prop="sex"
	    			:borderBottom="true"
	    			ref="item1"
					label-width="75"
	    	>
	    		<up-input
	    				v-model="expertForm.sex"
	    				border="none"
						placeholder="选择"
	    		></up-input>
				<template #right>
					<up-icon @close="showSex = true"
						name="arrow-right"
					></up-icon>
				</template>
	    	</up-form-item>
			<up-action-sheet
					:show="showSex"
					:actions="actions"
					title="请选择性别"
					@close="showSex = false"
					@select="sexSelect"
			>
			</up-action-sheet>
			
			<up-form-item
					label="毕业院校"
					prop="college"
					:borderBottom="true"
					ref="item1"
					label-width="75"
			>
				<up-input
						v-model="expertForm.college"
						border="none"
						placeholder="请输入您毕业的院校"
				></up-input>
			</up-form-item>
			
			<up-form-item
					label="学历"
					prop="degree"
					:borderBottom="true"
					ref="item1"
					label-width="75"
			>
				<up-input
						v-model="expertForm.degree"
						border="none"
						placeholder="选择"
				></up-input>
			</up-form-item>
			
			<up-form-item
					label="专业"
					prop="major"
					:borderBottom="true"
					ref="item1"
					label-width="75"
			>
				<up-input
						v-model="expertForm.major"
						border="none"
						placeholder="请输入您的专业"
				></up-input>
			</up-form-item>
			
			<up-form-item
					label="专攻方向"
					prop="speciality"
					:borderBottom="true"
					ref="item1"
					label-width="75"
			>
				<up-input
						v-model="expertForm.speciality"
						border="none"
						placeholder="请输入您的专长"
				></up-input>
			</up-form-item>
			
			<up-form-item
					label="手机号"
					prop="phone"
					:borderBottom="true"
					ref="item1"
					label-width="75"
			>
				<up-input
						v-model="expertForm.phone"
						border="none"
						placeholder="请输入您的手机号"
				></up-input>
			</up-form-item>
		</up-form>
		
		<button @click="addExpert">确定认证</button>
	</view>
</template>

<script setup>
	import {ref} from 'vue'
	const expertForm = ref({
		avatar:'',
		expertName:'',
		sex:'',
		college:'',
		degree:'',
		major:'',
		speciality:'',
		phone:''
	})
	const showSex = ref(false)
	const actions = ref(
	[
	  { name: '男' },  
	  { name: '女' },  
	  { name: '保密' },  
	]
	)
	const fileList1 = ref([]);
	
	const addExpert = () =>{
		uni.request({
			url:`http://127.0.0.1:3006/expert/addExpert`,
			method:'POST',
		    data: expertForm.value,
			success(res) {
				console.log(res.data)
				//弹出成功提示，跳转回上一个页面，并刷新
				uni.showToast({
					title: '认证成功，正在跳转首页...',
					duration: 2000
				});
				setTimeout(() => {
				    uni.switchTab({
				    	url:'/pages/index/index'
				    })
				  }, 1000);
			},
			fail(err){
				console.log(err)
			}
		})
	}
		
</script>

